 91	export type DeleteCustomerResult = { ok: true } | { ok: false; reason: string };
 92	
 93	export type UpdateCustomerInput = Pick<
 94	  CustomerDetail,
 95	  "companyName" | "contactName" | "email" | "status"
 96	>;
 97	
 98	export type UpdateCustomerResult = { ok: true; customer: CustomerDetail } | { ok: false; reason: string };
