100	export function deleteCustomer(
101	  customerId: string,
102	  options: { simulateFailure?: boolean } = {},
103	): DeleteCustomerResult {
104	  if (options.simulateFailure) {
105	    return { ok: false, reason: "削除に失敗しました。時間をおいて再試行してください。" };
106	  }
107	  const index = customerRecords.findIndex(({ id }) => id === customerId);
108	  if (index < 0) {
109	    return { ok: false, reason: "対象の顧客が見つかりません。" };
110	  }
111	  customerRecords.splice(index, 1);
112	  return { ok: true };
113	}
114	
115	export function updateCustomer(
116	  customerId: string,
117	  input: UpdateCustomerInput,
118	  options: { simulateFailure?: boolean } = {},
119	): UpdateCustomerResult {
120	  if (options.simulateFailure) {
121	    return { ok: false, reason: "更新に失敗しました。入力内容を保持したまま再試行できます。" };
122	  }
123	
124	  const customer = customerRecords.find(({ id }) => id === customerId);
125	  if (!customer) {
126	    return { ok: false, reason: "対象の顧客が見つかりません。" };
127	  }
128	
129	  customer.companyName = input.companyName;
130	  customer.contactName = input.contactName;
131	  customer.email = input.email;
132	  customer.status = input.status;
133	
134	  return {
135	    ok: true,
136	    customer: {
137	      id: customer.id,
138	      companyName: customer.companyName,
139	      contactName: customer.contactName,
140	      email: customer.email,
141	      phone: customer.phone,
142	      status: customer.status,
143	      note: customer.note,
144	    },
145	  };
146	}
